def add_title_page(doc):
    add_centered(doc, "МОСКОВСКИЙ ФИНАНСОВО-ЮРИДИЧЕСКИЙ\nУНИВЕРСИТЕТ МФЮА", size=12)
    doc.add_paragraph()
    add_plain_paragraph(doc, "Кафедра/ПЦК Гражданско-правовые дисциплины", first_line=False)
    add_plain_paragraph(doc, "Специальность 40.02.01 «Право и организация социального обеспечения»", first_line=False)
    doc.add_paragraph()
    doc.add_paragraph()
    p = add_plain_paragraph(doc, "«ДОПУСТИТЬ К ЗАЩИТЕ»", align=WD_ALIGN_PARAGRAPH.RIGHT, first_line=False, bold=True)
    p.runs[0].underline = True
    add_plain_paragraph(doc, "Зав. кафедрой/председатель ПЦК", align=WD_ALIGN_PARAGRAPH.RIGHT, first_line=False)
    add_plain_paragraph(doc, "______________________________", align=WD_ALIGN_PARAGRAPH.RIGHT, first_line=False)
    add_plain_paragraph(doc, "«___» ____________ 2026 г.", align=WD_ALIGN_PARAGRAPH.RIGHT, first_line=False)
    doc.add_paragraph()
    doc.add_paragraph()
    add_centered(doc, "ДИПЛОМНАЯ РАБОТА", size=16, bold=True)
    doc.add_paragraph()
    add_centered(doc, "На тему: Льготы в праве социального обеспечения\nРоссийской Федерации", bold=True, underline=True)
    add_centered(doc, "(тема дипломной работы)", size=12)
    doc.add_paragraph()
    table = doc.add_table(rows=3, cols=3)
    table.alignment = WD_TABLE_ALIGNMENT.CENTER
    widths = [Cm(4), Cm(5), Cm(6)]
    for row in table.rows:
        for idx, cell in enumerate(row.cells):
            cell.width = widths[idx]
    set_cell_text(table.cell(0, 0), "Обучающийся:", bold=True, size=10, align=WD_ALIGN_PARAGRAPH.LEFT)
    set_cell_text(table.cell(0, 1), "«___» ____________ 2026 г.\n(подпись)", size=9)
    set_cell_text(table.cell(0, 2), "________________________\n(Ф.И.О.)", size=9)
    set_cell_text(table.cell(1, 0), "Индивидуальный номер:", bold=True, size=10, align=WD_ALIGN_PARAGRAPH.LEFT)
    set_cell_text(table.cell(1, 1), "________________________\n(ИНС)", size=9)
    set_cell_text(table.cell(1, 2), "Группа ________________", size=9)
    set_cell_text(table.cell(2, 0), "Руководитель:", bold=True, size=10, align=WD_ALIGN_PARAGRAPH.LEFT)
    set_cell_text(table.cell(2, 1), "«___» ____________ 2026 г.\n(подпись)", size=9)
    set_cell_text(table.cell(2, 2), "________________________\n(Ф.И.О., ученая степень, звание)", size=9)
    for row in table.rows:
        for cell in row.cells:
            tc_pr = cell._tc.get_or_add_tcPr()
            borders = OxmlElement("w:tcBorders")
            for edge in ("top", "left", "bottom", "right", "insideH", "insideV"):
                tag = OxmlElement(f"w:{edge}")
                tag.set(qn("w:val"), "nil")
                borders.append(tag)
            tc_pr.append(borders)
    for _ in range(7):
        doc.add_paragraph()
    add_centered(doc, "Калининград, 2026")
    doc.add_page_break()


