def add_table(doc, rows):
    table = doc.add_table(rows=len(rows), cols=len(rows[0]))
    table.alignment = WD_TABLE_ALIGNMENT.CENTER
    table.style = "Table Grid"
    for i, row in enumerate(rows):
        for j, value in enumerate(row):
            set_cell_text(table.cell(i, j), value, bold=(i == 0), size=12, align=WD_ALIGN_PARAGRAPH.CENTER if i == 0 else WD_ALIGN_PARAGRAPH.LEFT)
    return table


def main():
    doc = Document()
    configure_document(doc)
    footer = doc.sections[0].footer
    add_page_number(footer.paragraphs[0])

    add_title_page(doc)
    add_toc(doc)

    add_section_title(doc, "Введение")
    for paragraph in INTRO:
        add_plain_paragraph(doc, paragraph)

    for chapter_title, subsections in SECTIONS:
        doc.add_page_break()
        add_section_title(doc, chapter_title)
        for subsection_title, paragraphs in subsections:
            add_section_title(doc, subsection_title)
            for paragraph in paragraphs:
                add_plain_paragraph(doc, paragraph)

    doc.add_page_break()
    add_section_title(doc, "Заключение")
    for paragraph in CONCLUSION:
        add_plain_paragraph(doc, paragraph)

    doc.add_page_break()
    add_section_title(doc, "Список использованных источников")
    for source in SOURCES:
        is_heading = source in ["I. Нормативные правовые акты", "II. Акты судебных органов", "III. Литература", "IV. Ресурсы сети Интернет"]
        add_plain_paragraph(doc, source, first_line=False, bold=is_heading)

    doc.add_page_break()
    add_section_title(doc, "Приложение 1")
    add_section_title(doc, "Основные категории граждан, имеющих право на льготы")
    add_table(doc, APPENDIX_1)

    doc.add_page_break()
    add_section_title(doc, "Приложение 2")
    add_section_title(doc, "Классификация льгот в праве социального обеспечения")
    add_table(doc, APPENDIX_2)

    doc.save(OUTPUT)
    print(OUTPUT)


if __name__ == "__main__":
    main()
